insert into public.heritage_entries (id,slug,name,kind,region,translations,latitude,longitude,image,image_author,image_license,image_source,sources,status,verification,updated_at) values ('00000000-0000-4000-8000-000000000001','hue','Quần thể di tích Cố đô Huế','monument','Huế','{"vi":{"summary":"Dấu ấn kinh đô triều Nguyễn bên dòng sông Hương.","story":"Cố đô Huế lưu giữ kiến trúc kinh thành, cung điện và lăng tẩm của triều Nguyễn. Cảnh quan tự nhiên là một phần của cách tổ chức không gian di sản.","detail":"Quan sát sự liên kết giữa các cổng, trục kiến trúc và cảnh quan. Ảnh thể hiện Ngọ Môn trong khu vực Hoàng thành."},"en":{"summary":"The Nguyễn imperial capital beside the Hương River.","story":"Huế preserves the citadel, palaces and royal tombs of the Nguyễn dynasty. Its natural landscape forms part of the heritage’s spatial design.","detail":"Look at the relationship between gates, architectural axes and landscape. The photograph shows Ngọ Môn in the Imperial City."},"zh":{"summary":"Hương河畔，阮朝都城的文化印记。","story":"Huế保留了阮朝的城堡、宫殿和皇陵。自然景观是遗产空间布局的重要组成部分。","detail":"观察城门、建筑轴线与景观的联系。照片为皇城内的Ngọ Môn。"}}',16.46972222,107.57777778,'/images/hue.jpg','NguyenThanhBac123','CC0','https://commons.wikimedia.org/wiki/File:%C4%90%E1%BA%A1i_n%E1%BB%99i.jpg','[{"title":"Quần thể di tích Cố đô Huế","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/678/","accessed":"2026-10-26"},{"title":"Quần thể di tích Cố đô Huế","publisher":"Wikipedia · WGS84","url":"https://en.wikipedia.org/wiki/Imperial_City_of_Hu%E1%BA%BF","accessed":"2026-10-26"}]','published','reference','2026-10-26T00:00:00Z') on conflict (id) do nothing;
insert into public.heritage_entries (id,slug,name,kind,region,translations,latitude,longitude,image,image_author,image_license,image_source,sources,status,verification,updated_at) values ('00000000-0000-4000-8000-000000000002','hoi-an','Đô thị cổ Hội An','architecture','Hội An','{"vi":{"summary":"Những nếp nhà kể câu chuyện của một thương cảng xưa.","story":"Hội An là ví dụ được bảo tồn về một thương cảng Đông Nam Á phát triển từ thế kỷ XV đến XIX. Đô thị phản ánh sự giao thoa giữa văn hóa bản địa và các ảnh hưởng bên ngoài.","detail":"Nhìn kết cấu nhà gỗ và cách những dãy phố kết nối với dòng sông."},"en":{"summary":"Old houses tell the story of a historic trading port.","story":"Hội An preserves the fabric of a Southeast Asian trading port active from the 15th to the 19th centuries, reflecting local and foreign cultural influences.","detail":"Look for timber structures and the relationship between streets and the river."},"zh":{"summary":"古老民居，诉说昔日商港的故事。","story":"Hội An保留了十五至十九世纪东南亚商港的城市格局，反映本土文化与外来文化的交融。","detail":"留意木结构房屋，以及街道与河流之间的联系。"}}',15.87972222,108.33194444,'/images/hoi-an.jpg','xiquinhosilva','CC BY 2.0','https://commons.wikimedia.org/wiki/File:10549-Hoi-An_(37621348460).jpg','[{"title":"Đô thị cổ Hội An","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/948/","accessed":"2026-10-26"},{"title":"Đô thị cổ Hội An","publisher":"Wikipedia · WGS84","url":"https://en.wikipedia.org/wiki/Hội_An_(city)","accessed":"2026-10-26"}]','published','reference','2026-10-26T00:00:00Z') on conflict (id) do nothing;
insert into public.heritage_entries (id,slug,name,kind,region,translations,latitude,longitude,image,image_author,image_license,image_source,sources,status,verification,updated_at) values ('00000000-0000-4000-8000-000000000003','my-son','Thánh địa Mỹ Sơn','monument','Mỹ Sơn','{"vi":{"summary":"Những tháp đền lưu giữ dấu ấn văn hóa Champa.","story":"Mỹ Sơn là quần thể tháp đền gắn với đời sống tôn giáo và chính trị của vương quốc Champa. Di tích cho thấy ảnh hưởng của Ấn Độ giáo trong văn hóa khu vực.","detail":"Quan sát hình khối tháp và các chi tiết trang trí; không chạm lên bề mặt di tích."},"en":{"summary":"Temple towers bearing traces of Champa culture.","story":"Mỹ Sơn is a group of temple towers associated with the religious and political life of Champa, showing Hindu influences in the region.","detail":"Observe tower forms and decorative details without touching the historic surfaces."},"zh":{"summary":"塔庙之间，留存Champa文化的印记。","story":"Mỹ Sơn塔庙群与Champa的宗教和政治生活密切相关，体现印度教对当地文化的影响。","detail":"观察塔身造型与装饰细节，请勿触摸遗迹表面。"}}',15.76666667,108.11666667,'/images/my-son.jpg','Chainwit.','CC BY 4.0','https://commons.wikimedia.org/wiki/File:2024_-_M%E1%BB%B9_S%C6%A1n_Group_B,_C_and_D_-_img_23.jpg','[{"title":"Thánh địa Mỹ Sơn","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/949/","accessed":"2026-10-26"},{"title":"Thánh địa Mỹ Sơn","publisher":"Wikipedia · WGS84","url":"https://en.wikipedia.org/wiki/My_Son_Sanctuary","accessed":"2026-10-26"}]','published','reference','2026-10-26T00:00:00Z') on conflict (id) do nothing;
insert into public.heritage_entries (id,slug,name,kind,region,translations,latitude,longitude,image,image_author,image_license,image_source,sources,status,verification,updated_at) values ('00000000-0000-4000-8000-000000000004','ha-long','Vịnh Hạ Long – Quần đảo Cát Bà','nature','Hạ Long – Cát Bà','{"vi":{"summary":"Một cảnh quan biển được tạo nên từ núi đá vôi và nước.","story":"Hạ Long – Cát Bà nổi bật với những đảo đá vôi vươn lên từ biển. Cảnh quan karst biển và các hệ sinh thái góp phần tạo nên giá trị của di sản.","detail":"Theo dõi sự thay đổi của hình dáng đảo từ các góc nhìn; tuân thủ tuyến tham quan được phép."},"en":{"summary":"A seascape shaped by limestone and water.","story":"Hạ Long – Cát Bà is distinguished by limestone islands rising from the sea. Marine karst landscapes and ecosystems contribute to its heritage value.","detail":"Observe how island shapes change with your viewpoint and follow approved visitor routes."},"zh":{"summary":"石灰岩与海水共同塑造的海上风景。","story":"Hạ Long – Cát Bà以海中耸立的石灰岩岛屿闻名。海洋喀斯特地貌及生态系统构成其遗产价值。","detail":"从不同视角观察岛屿形状，遵循获准的游览路线。"}}',20.9,107.2,'/images/ha-long.jpg','Taewangkorea','CC BY-SA 4.0','https://commons.wikimedia.org/wiki/File:Ha_Long_Bay_in_2019.jpg','[{"title":"Vịnh Hạ Long – Quần đảo Cát Bà","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/672/","accessed":"2026-10-26"},{"title":"Vịnh Hạ Long – Quần đảo Cát Bà","publisher":"Wikipedia · WGS84","url":"https://en.wikipedia.org/wiki/H%E1%BA%A1_Long_Bay","accessed":"2026-10-26"}]','published','reference','2026-10-26T00:00:00Z') on conflict (id) do nothing;
insert into public.heritage_entries (id,slug,name,kind,region,translations,latitude,longitude,image,image_author,image_license,image_source,sources,status,verification,updated_at) values ('00000000-0000-4000-8000-000000000005','thang-long','Hoàng thành Thăng Long','monument','Hà Nội','{"vi":{"summary":"Những lớp lịch sử của trung tâm quyền lực xưa tại Hà Nội.","story":"Hoàng thành Thăng Long gắn với triều Lý từ thế kỷ XI. Kiến trúc và dấu tích khảo cổ phản ánh nhiều lớp văn hóa của vùng đồng bằng sông Hồng.","detail":"Đọc biển diễn giải để phân biệt công trình hiện hữu với dấu tích khảo cổ dưới lòng đất."},"en":{"summary":"Layers of history at a former centre of power in Hà Nội.","story":"Hoàng thành Thăng Long is associated with the Lý dynasty from the 11th century. Its buildings and archaeology reflect cultural layers of the Red River Delta.","detail":"Use interpretation signs to distinguish standing structures from archaeological remains."},"zh":{"summary":"Hà Nội古代权力中心，层层叠叠的历史。","story":"Hoàng thành Thăng Long与十一世纪的李朝相关，建筑与考古遗迹展现红河三角洲的文化层次。","detail":"阅读解说牌，区分现存建筑与地下考古遗迹。"}}',21.03944444,105.83722222,'/images/thang-long.jpg','Phan Minh Tuấn','CC BY-SA 4.0','https://commons.wikimedia.org/wiki/File:%C4%90oan_M%C3%B4n,_Ho%C3%A0ng_th%C3%A0nh_Th%C4%83ng_Long,_H%C3%A0_N%E1%BB%99i_001.JPG','[{"title":"Hoàng thành Thăng Long","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/1328/","accessed":"2026-10-26"},{"title":"Hoàng thành Thăng Long","publisher":"Wikipedia · WGS84","url":"https://en.wikipedia.org/wiki/Imperial_Citadel_of_Th%C4%83ng_Long","accessed":"2026-10-26"}]','published','reference','2026-10-26T00:00:00Z') on conflict (id) do nothing;
insert into public.heritage_entries (id,slug,name,kind,region,translations,latitude,longitude,image,image_author,image_license,image_source,sources,status,verification,updated_at) values ('00000000-0000-4000-8000-000000000006','trang-an','Quần thể danh thắng Tràng An','nature','Ninh Bình','{"vi":{"summary":"Núi đá, thung nước và dấu vết con người qua thời gian.","story":"Tràng An kết hợp cảnh quan núi đá vôi với dấu tích con người trong hang động. Không gian di sản còn bao gồm đền, chùa, làng và đồng ruộng.","detail":"Quan sát mối quan hệ giữa vách đá, thung ngập nước và đời sống trong cảnh quan."},"en":{"summary":"Limestone peaks, flooded valleys and traces of human life.","story":"Tràng An combines limestone landscapes with evidence of human activity in caves. The heritage setting also includes temples, villages and rice fields.","detail":"Observe how cliffs and flooded valleys connect with human life in the landscape."},"zh":{"summary":"石灰岩峰林、水谷与人类活动的痕迹。","story":"Tràng An将石灰岩景观与洞穴中的人类活动遗迹结合起来。遗产还包括庙宇、村庄和稻田。","detail":"观察峭壁、水谷与景观中人类生活之间的联系。"}}',20.25666667,105.89638889,'/images/trang-an.jpg','Kien1980v (thảo luận)','Public domain','https://commons.wikimedia.org/wiki/File:Muaxuantamcoc.jpg','[{"title":"Quần thể danh thắng Tràng An","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/1438/","accessed":"2026-10-26"},{"title":"Quần thể danh thắng Tràng An","publisher":"Wikipedia · WGS84","url":"https://en.wikipedia.org/wiki/Tr%C3%A0ng_An_Scenic_Landscape_Complex","accessed":"2026-10-26"}]','published','reference','2026-10-26T00:00:00Z') on conflict (id) do nothing;
insert into public.challenges (id,entry_id,translations,points,badge,status,expires_at) values ('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','{"vi":{"title":"Đọc dấu ấn kinh đô","description":"Đọc câu chuyện Cố đô Huế và nhận huy hiệu Huế khi trả lời đúng.","question":"Cố đô Huế gắn với triều đại nào trong bài đọc?","options":["Triều Nguyễn","Triều Lý","Triều Trần","Triều Đinh"]},"en":{"title":"Read the imperial legacy","description":"Read the Huế story and earn the Huế badge with a correct answer.","question":"Which dynasty is associated with Huế in the article?","options":["Nguyễn dynasty","Lý dynasty","Trần dynasty","Đinh dynasty"]},"zh":{"title":"读懂古都印记","description":"阅读Huế故事，答对问题即可获得Huế徽章。","question":"文章中的Huế与哪个朝代相关？","options":["阮朝","李朝","陈朝","丁朝"]}}',20,'Huế','published',null) on conflict (id) do nothing;
insert into private.challenge_answers (challenge_id,correct_option) values ('10000000-0000-4000-8000-000000000001',0) on conflict do nothing;
insert into public.challenges (id,entry_id,translations,points,badge,status,expires_at) values ('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','{"vi":{"title":"Chuyện kể từ phố cổ","description":"Đọc câu chuyện Hội An, khám phá vai trò của một đô thị ven sông.","question":"Hội An được giới thiệu như loại đô thị nào?","options":["Thương cảng","Kinh đô","Pháo đài quân sự","Khu công nghiệp"]},"en":{"title":"Stories from the old town","description":"Read the Hội An story and explore its role as a riverside town.","question":"How is Hội An described in the article?","options":["A trading port","An imperial capital","A military fortress","An industrial zone"]},"zh":{"title":"古城里的故事","description":"阅读Hội An故事，探索河畔城市的历史作用。","question":"文章如何介绍Hội An？","options":["商港","皇都","军事堡垒","工业区"]}}',20,'Hội An','published',null) on conflict (id) do nothing;
insert into private.challenge_answers (challenge_id,correct_option) values ('10000000-0000-4000-8000-000000000002',0) on conflict do nothing;
